node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1});
 page.on('pageerror',e=>console.error('PAGEERROR',e.message));
 await page.goto('http://localhost:3002');
 await page.screenshot({path:'/tmp/opencode/moxie-mobile.jpg',type:'jpeg',quality:75});
 await page.getByRole('button',{name:/mulai main/i}).click();
 await page.locator('#full-name').fill('Dimas Pratama');
 await page.locator('#phone').fill('081234567890');
 await page.locator('#consent').check();
 await page.getByRole('button',{name:/lanjut ke kuis/i}).click();
 for(let i=0;i<5;i++){
   if(!(await page.locator('#quiz-step').innerText()).includes(`Pertanyaan ${i+1} dari 5`)) throw Error('bad quiz step '+i);
   await page.locator('[data-option="0"]').click();
 }
 await page.locator('#result').waitFor({state:'visible'});
 const result=await page.locator('#result-card').innerText();
 const stored=await page.evaluate(()=>JSON.parse(localStorage.getItem('moxieQuizLead')));
 console.log(JSON.stringify({title:await page.title(),quizResult:result.slice(0,120),stored,horizontalOverflow:await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth)},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
